"""Independent nonnegative feasibility certificate; do not route failed fitted loads in flood."""
from observed_load_common_v1 import *
from scipy.sparse import load_npz
from scipy.optimize import linprog
import datetime as dt

def main():
 dem=load(REP/'multi_routing_demands.npz');order=load(P/'basis_order.npz')['source_expanded_od_index'];base=dem['base'][order];A=load_npz(P/'screenline_incidence.npz')[:,base].toarray();patterns=np.unique(A.T,axis=0);o=pd.read_csv(P/'normal_observation_constraints.csv',dtype={'observation_section_id':str,'count_authority_code':str,'count_unit_id':str});y=o.observed_small_daytime12h.to_numpy();supported=o.supported.to_numpy();Q=float(dem['period_weights'][order[base],4].sum());V=patterns[:,supported].T*Q/y[supported,None];nr=V.shape[0];ng=V.shape[1];AA=np.vstack([np.column_stack([V,-np.ones(nr)]),np.column_stack([-V,-np.ones(nr)])]);bb=np.r_[np.ones(nr),-np.ones(nr)];objective=np.r_[np.zeros(ng),1.];lp=linprog(objective,A_ub=AA,b_ub=bb,bounds=[(0,None)]*(ng+1),method='highs');assert lp.success;rho=float(lp.x[-1]);sol=lp.x[:-1];pred=V@sol;dual=lp.ineqlin.marginals;active=[];supported_rows=o[supported].reset_index(drop=True)
 for k,weight in enumerate(dual):
  if abs(weight)<1e-8:continue
  i=k%nr;r=supported_rows.iloc[i];active.append({'screen_index':int(r.screen_index),'observation_section_id':r.observation_section_id,'road_class':r.road_class,'source_route_name':r.source_route_name,'direction_of_constraint':'upper'if k<nr else'lower','observed_small12h':float(r.observed_small_daytime12h),'best_possible_ratio_at_minimax':float(pred[i]),'dual_multiplier':float(weight),'note':'Active evidence for the fixed-route incompatibility;not proof an official count is wrong'})
 save('infeasible_constraint_certificate.csv',active);dependency=[]
 for lower in [r for r in active if r['direction_of_constraint']=='lower']:
  for upper in [r for r in active if r['direction_of_constraint']=='upper']:
   i=lower['screen_index'];j=upper['screen_index'];dominates=bool((A[i]<=A[j]).all());dependency.append({'required_flow_leq_screen':lower['observation_section_id'],'required_flow_geq_screen':upper['observation_section_id'],'all_prior_base_routes_obey_leq':dominates,'first_observed_small12h':y[i],'second_observed_small12h':y[j],'first20percent_band_lower':.8*y[i],'second20percent_band_upper':1.2*y[j],'bands_contradict_ordering':bool(dominates and .8*y[i]>1.2*y[j]),'same_matched_road_indices':str(o.loc[i,'matched_road_indices'])==str(o.loc[j,'matched_road_indices'])})
 save('fixed_route_flow_dependency.csv',dependency);coverage=[]
 for cls in ['ordinary','expressway']:
  m=o.road_class.eq(cls);coverage.append({'road_class':cls,'observed_screens':int(m.sum()),'route_supported_screens':int((m&o.supported).sum()),'structural_uncovered_screens':int((m&~o.supported).sum()),'uncovered_observed_small12h_passages':float(o.loc[m&~o.supported,'observed_small_daytime12h'].sum()),'fraction_of_observed_passage_sum_uncovered':float(o.loc[m&~o.supported,'observed_small_daytime12h'].sum()/o.loc[m,'observed_small_daytime12h'].sum())})
 save('structural_coverage_summary.csv',coverage);fit=json.loads((R/'inverse_summary.json').read_text());checks={'same80supported_and5uncovered':int(supported.sum())==80 and int((~supported).sum())==5,'independent_minimax_confirms20band_infeasible':rho>.2+1e-7,'nonnegative_minimax_solution':bool((sol>=0).all()),'minimax_primal_constraints_hold':bool((AA@lp.x<=bb+1e-7).all()),'dual_certificate_nonempty':len(active)>0,'failed_fit_not_relabelled_qualified':not fit['partial_supported_constraint_gate_passed']and not fit['full_baseline_gate_passed'],'frozen_sources_unchanged':all(sha(ROOT/p)==v for p,v in json.loads((P/'input_bindings.json').read_text())['sha256'].items())};summary={'completed_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'status':'baseline_gate_failed_before_flood_traffic','minimum_necessary_uniform_relative_error_band':rho,'requested_band':.2,'certificate_active_constraints':active,'coverage':coverage,'fixed_route_dependency':dependency,'optimizer_failure_not_the_cause':'Independent linear-program feasibility and minimax solve prove incompatibility on this route basis without fallback weight bounds. It does not prove incompatibility for all real routes or OD.','load_drafts_role':'low/central/high residual-fit diagnostics only;not approved input to storm traffic','existing_flood_snapshot_prepared':True,'new_flood_traffic_routing_executed':False,'new_hydraulics':False,'affected_people':False,'checks':checks};dump(R/'feasibility_gate.json',summary);dump(R/'validation.json',{'passed':all(checks.values()),'meaning':'Integrity of the failed feasibility result,not approval of the traffic model','checks':checks});dump(R/'execution_state.json',{'status':'stopped_at_failed_baseline_gate','normal_route_basis_complete':True,'observation_feasibility_passed':False,'diagnostic_loads_saved':True,'flood_traffic_not_started':True});print(json.dumps(summary,ensure_ascii=False,indent=2))
 if not all(checks.values()):raise SystemExit('Feasibility diagnosis integrity failure')
if __name__=='__main__':main()
